maintenance.scss:
* {
    box-sizing: border-box;
}

body {
    -webkit-align-items: center;
    align-items: center;
    background: #888 url("../img/coming-soon.jpg") no-repeat center center;
    background-size: cover;

    -ms-box-orient: horizontal;
    color: #798289;
    display: -webkit-flex;
    display: -ms-flexbox;
    display: flex;
    -ms-flex-align: center;
    -ms-flex-pack: space-around;
    font-family: Helvetica, Arial, Sans-Serif;
    font-size: 0.8em;
    height: 100vh;

    -webkit-justify-content: space-around;
    justify-content: space-around;
    line-height: 1.5em;
    margin: 0;
    min-height: 480px;
    min-width: 320px;
    padding: 20px 30px;
}

main {
    background-color: #fff;
    box-shadow: 0 2px 0 0 rgba(0, 0, 0, 0.07);
    display: block;
    padding: 20px 30px;
    text-align: center;
}

section {
    margin-bottom: 40px;
}

fieldset {
    border: 0;
    padding: 0;
}

legend {
    border: 0;
    clip: rect(0 0 0 0);
    height: 1px;
    margin: -1px;
    overflow: hidden;
    padding: 0;
    position: absolute !important;
    width: 1px;
}

label,
input {
    display: block;
    height: 30px;
    line-height: 30px;
    width: 100%;
}

label {
    color: #313b47;
    font-size: 14px;
    font-weight: bold;
    text-align: center;
}

input {
    -webkit-appearance: none;
    border-radius: 2px;
    border-style: solid;
    width: 100%;
}

input[type=text] {
    background-color: #f7f8f9;
    border: 1px solid #e1e6eb;
    margin-bottom: 1rem;
    padding: 0 1em;
}

input[type=submit] {
    background: #00abc9;
    border: 0;
    color: #fff;
    cursor: pointer;
    font-size: 12px;
    padding: 0 15px;
}

a {
    color: #00b9d3;
    margin: 0 5px;
    text-decoration: none;
}

h1 {
    color: #3c4043;
    font-size: 24px;
    font-weight: 300;
    margin-top: 15px;
}

div p {
    margin-bottom: 0;
    margin-top: 0;
}

.form-field--error {
    margin-bottom: 1rem;
}

.form-field--error input[type=text] {
    margin-bottom: 0;
}

.form-field--error .form-inlineMessage {
    color: #ac0005;
    margin-top: 0.375rem;
    width: 100%;
}

.powered-by {
    color: #acb3be;
    font-size: 11px;
    font-style: italic;
    line-height: 24px;
}

.powered-by a {
    background: url("../img/bc_logo_sprite.png") 0 -75px no-repeat;
    display: inline-block;
    height: 22px;
    opacity: 0.7;
    text-indent: -9999px;
    width: 95px;
}

.powered-by a:hover {
    opacity: 1;
}
@media screen and (min-width: 540px) {
    body {
        font-size: 1em;
    }

    main {
        margin: 0 auto;
        padding: 45px 60px;
        width: 500px;
    }

    label,
    input {
        display: inline-block;
        margin-right: 10px;
        width: auto;
    }

    label {
        text-align: left;
    }

    input[type=text] {
        margin-bottom: 0;
        margin-right: 10px;
    }

    .form-field {
        display: inline-block;
        position: relative;
    }

    .form-field--error .form-inlineMessage {
        left: 100px;
        position: absolute;
        top: 30px;
    }
}

assets/scss/user-authentication.scss:
@import "global-objects";

.alertBoxInfo{
    padding: 10px 50px 10px 16px;
    border-radius: 8px;
    border: 1px solid #707070;

    &.alertBoxInfo {
      padding: 10px 10px 10px 16px;
    }
    
    .alertBox-message, .alertBoxInfo-message{
        font-family: var(--sans-ext);
        font-size: 14px;
        font-weight: 400;
        line-height: 22px;
        text-align: left;
        color: #000000;
        margin: 0;
        span{
          width: 100%;
        }
    }
    
    .alertBox-column{
        vertical-align: text-top;
    }
    
    .icon {
        height: 18px;
        width: 20px;
        margin: -2px 0 0 0;
    }

    .alertBox-close{
        cursor: pointer;
        padding: 0;
        position: absolute;
        top: 0;
        width: 30px;
        height: 43px;
        right: 0;
        border-radius: 8px;
        svg{
            width: 22px;
            height: 22px;
            display: block;
            margin: 0 auto;
            fill: #838383 !important;
        }
        &:hover, &:focus {
            background-color:transparent !important;
            border-color: transparent;
        }
    }
    

  &.alertBoxInfo--info,
   &.alertBox--info{
       background: #E6F4FF;
       border-color:#91CAFF;
       svg{ fill: #000000; }
   }
   
   &.alertBoxInfo--success,
   &.alertBox--success{
       background: #F6FFED;
       border-color:#B7EB8F;
       svg{ fill: #52C41A; }
   }
   
   &.alertBoxInfo--warning,
   &.alertBox--warning{
       background:#FFFBE6;
       border-color: #FFE58F;
       svg{ fill:#FAAD14; }
   }
   
   &.alertBoxInfo--error,
   &.alertBox--error {
       background:#FFF1F0;
       border-color: #FFA39E;
       svg{ fill:#FF4D4F; }
   }
   
}

.bc-authentication-model {
    display: none;
    width: 100%;
    height: 100%;
    position: fixed;
    padding: 15px;
    left: 0;
    top: 0;
    z-index: 9999999999;
    background: rgba($color: #000000, $alpha: 0.5);
    align-items: center;
    justify-content: center;
    backdrop-filter: blur(7px);

    .alertBox{
        display: none;
        margin-top: 0 !important;
        .icon{
            display: none;
            margin: 0 !important;
            position: relative;
            top: 2px;
        }
    }

    .form-row {
        display: flex;
        @include md-phone{
            flex-wrap: wrap;
        }
    }

    .form-field{
        width: 100%;
        margin-bottom:10px;
        .form-label{
            font-size: 15px;
            color:#000000;
            small {
                float: left;
                font-size: 20px;
                color: #FF7875;
                padding-right: 5px;
                margin: 0;
            }
        }
        .form-select {
            color: #333333;
        }
        .form-input, .form-select {
            border-radius: 0;
            margin: 0;
            height: auto;
            padding: 10px;
            box-shadow: none;
            background-position: right center;
            color: #000;
            font-size: 15px;
        }
    }

    .form-actions{
        margin: 0;
        text-align: left;
        width: 100%;
        display: flex;
        align-items: center;
        flex-wrap: wrap;
    }
    
    .button{
        width: auto;
        margin: 0;
        padding: 10px 16px;
        border-radius: 6px;
        font-family: var(--sans-ext);
        font-size: 14px;
        line-height: 16px;
        font-weight: 400;
        text-align: left;
        text-transform: none;
        + .button{ 
            margin:0 0 0 15px;
        }
        
        &[disabled]{
            opacity: 0.6;
            pointer-events: none;
        }
    }
    
    .button--primary{
        background: #000000;
        border-color: #000000;
        color: #fff;
        &:hover{
            border-color: #000000;
            background: #ffffff;color:#000000;
        }
    }

    .buttonSecondary{
        border-color: #CCCCCC;
        + .buttonSecondary{
            margin-left: 15px;
        }
        &:hover{
            border-color: #CCCCCC;
            color: #000000;
        }
    }

    .view-password-action {
        position: relative;
        .view-password-icon{
            position: absolute;
            right: 5px;
            width: 30px;
            height: 30px;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            top: 5px;
            &:hover, &.is-active{
                svg{
                    path{
                        fill: #000000;
                    }
                }
            }
        }
    }

    /* Change the white to any color */
    input:-webkit-autofill,
    input:-webkit-autofill:hover, 
    input:-webkit-autofill:focus, 
    input:-webkit-autofill:active{
        -webkit-box-shadow: 0 0 0 30px #fff inset !important;
    }
    
    @include md-phone {
        padding: 0; 
    }

}

.bc-auth-inner{
    width: 100%;
    max-width: 1080px;
    height: auto;
    max-height: 85vh;
    overflow: auto;
    background: #fff;
    border-radius: 8px;
    padding: 0;
    box-shadow: 0px 6px 16px 0px rgba($color: #000000, $alpha: 0.08);
    @include md-phone{
        border-radius: 0px;
        height: 100%;
        max-height: none; 
    }

    &.is-layout-1{
        position: relative;
     .form-content{
         width: 100%;
         margin-bottom: 20px;
        // max-height: 550px;
        // overflow-x: hidden;
        // overflow-y: auto;
     }   
    }

}

.bc-auth-header{
    padding:16px 24px;
    display: flex;
    width: 100%;
    position: sticky;
    top: 0;
    background: #fff;
    z-index: 1;

    @include md-phone{
        padding: 15px;
    }

    h2, .bc-hdr-h2 {
        margin: 0;
        color: #000000;
        font-family: var(--sans-ext);
        font-size: 16px;
        line-height: 22px;
        font-weight: 600;
        text-align: left;
        padding-right: 40px;
    }

    .bc-auth-close{
        width: 33px;
        height: 33px;
        position: absolute;
        right: 5px;
        top: 5px;
        padding: 0;
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 0;
        cursor: pointer;
        background: #fff;
        &:hover{
            background: #fff;
            svg{
                fill: #000000;
            }
        }
        svg{
            width: 23px;
            height: 23px;
        }
    }

}

.bc-auth-footer{
    padding:0 24px 30px 24px;
    .auth-footer-inner{
        border-top: 1px solid rgba($color: #000000, $alpha: 0.06);
        padding-top: 15px;
    }
    a{
        color: #1677FF;
        &:hover{
            background: #fff;
            text-decoration: underline !important;
            text-underline-offset: 5px;
        }
    }

    .popup-footer-notes{
        font-size: 12px;
        color: rgba($color: #000000, $alpha: 0.65)
    }
    
    @include md-phone{
        padding: 15px;
        flex-wrap: wrap;
    }
}

.bc-auth-content{
    width: 100%;
    padding: 10px 24px 20px 24px;
    display: flex;
    gap: 50px;
    position: relative;

    @include md-phone{
        padding: 15px;
        flex-wrap: wrap;
    }
    
    .bc-auth-left{
        width: 50%;
        @include md-phone{
            width: 100%;
        }
    }

    .bc-auth-right{
        width: 50%;
        @include md-phone{
            width: 100%;
        }
        ul{
            width: 100%;
            list-style: none;
            padding: 0;
            margin: 0 0 25px 0;
            li{
                position: relative;
                &::before{
                    content: '';
                    width: 10px;
                    height: 10px;
                    background: #000000;
                    border-radius: 50%;
                    position: absolute;
                    left: 0;
                    top: 4px;
                }
                margin: 0 0 10px 0;
                padding-left: 20px;
                font-size: 15px;
                line-height: 18px;
                font-weight: 400;
                text-align: left;
                color: #000000;
            }
        }
    }

    h3, .h3{
        font-size: 16px;
        font-weight: 600;
        line-height: 28px;
        text-align: left;
        color: #000000;
        margin: 0 0 25px 0;
    }
    h4, .h4{
        font-size: 16px;
        font-weight: 600;
        line-height: 24px;
        text-align: left;
        text-align: left;
        color: #000000;
        margin: 0 0 15px 0;
        span{
            display: block;
            font-size: 14px;
            font-weight: 400;
            line-height: 22px;
        }
    }

    .model-login-form{
        width: 100%;
        position: relative;
    }
    
    .login-reset-password{
        margin: 0 0 0 25px;
        padding: 0;
        background: #fff;
        height: auto;
        width: auto;
        font-size: 14px;
        font-weight: 400;
        line-height: 22px;
        text-align: left;
        color: #1677FF;

        &:hover{
            background: #fff;
            text-decoration: underline;
            text-underline-offset: 5px;
        }
    }

}

.step-sign-in{
    display: none;
    .h3{
        font-size: 20px;
        font-weight: 700;
        margin: 0 0 5px 0;
    }
    .h4{
        font-size: 15px;
        font-weight: 400;
        line-height: 22px;
        text-align: left;
        margin: 0 0 20px 0;
        @include md-phone{
            br{
                display: none;
            }
        }
    }
}

.step-navigate-existing-customer{
    display: none;
    max-width: 520px;
}

.step-search-by-info{
    display: none;
    max-width: 520px;
}

.step-search-by-orderNumber{
    display: none;
    max-width: 520px;
}

.step-search-result{
    display: none;
    max-width: 520px;
    h3{
        margin: 0;
    }
    .result-count{
        font-size: 14px;
        font-weight: 400;
        line-height: 22px;
        text-align: left;
        margin: 0 0 20px 0;
    }
    .bc-auth-compnay-lists{
        width: 100%;
        .bc-auth-compnay-list{
            width: 100%;
            padding: 10px 10px 10px 45px;
            border: 1px solid #CCCCCC;
            border-radius: 8px;
            margin: 0 0 15px 0;
            cursor: pointer;
            font-size: 14px;
            font-weight: 400;
            line-height: 22px;
            text-align: left;
            position: relative;
            user-select: none;

            &::before{
                content: '';
                width: 15px;
                height: 15px;
                border:1px solid #CCCCCC;
                position: absolute;
                left: 15px;
                top: 15px;
                border-radius: 50%;
            }

            &.is-active{
                &::before{
                    border:1px solid #000000;
                }
                &::after{
                    content: '';
                    width: 9px;
                    height: 9px;
                    background: #000000;
                    border: 1px solid #000000;
                    position: absolute;
                    left: 17.5px;
                    top: 17.5px;
                    border-radius: 50%;
                }
            }

            &:hover, &.is-active{
                border: 1px solid #005AAF;
            }
        }
    }
}


.step-account-information{
    display: none;
    max-width: 520px;

    .profile-registration-parent-company{
        margin: 15px 0 25px 0;
        font-size: 14px;
    }

}


.content-email-newsletter{
    p, label{
        margin: 0;
        font-size: 14px;
        font-weight: 400;
        line-height: 22px;
        text-align: left;
    }
    p{
        margin: 0 0 10px 0;
    }
    label{
        display: flex;
        gap: 10px;
        align-items: center;
        input{
            margin: 0;
        }
    }
}


.step-account-not-found{
    display: none;
    max-width: 520px;
}
.step-account-success-message{
    display: none;
    max-width: 520px;
}
.step-session-active-message{
    display: none;
}

.step-counters{
    width: 100%;
    display: flex;
    flex: 1;
    margin-bottom:20px;
    border-bottom: 1px solid rgba($color: #000000, $alpha: 0.06);
    padding-bottom: 15px;
    @include emd-phone{
        flex-wrap: wrap;
        gap: 15px;
    }

    .step-counter{
        width: 100%;
        display: flex;
        align-items: center;
        gap: 10px;
        position: relative;
        z-index: 0;

        @include emd-phone{
            width: calc(50% - 10px);
        }

        .step-number{
            display: inline-flex;
            border-radius: 50%;
            width: 24px;
            height: 24px;
            background: #cccccc;
            font-family: var(--sans-ext);
            font-weight: 400;
            font-style: Regular;
            font-size: 14px;
            line-height: 22px;
            align-items: center;
            justify-content: center;
            position: relative;
            z-index: 1;
        }

        .step-title{
            width: calc(100% - 30px);
            font-family: var(--sans-ext);
            font-weight: 400;
            font-size: 14px;
            line-height: 22px;
            display: inline-flex;
            background: #fff;
            padding-right: 10px;
            background: #fff;
            position: relative;
            z-index: 1;
        }

        &::after{
            top: 50%;
            right: 10px;
            position: absolute;
            content: '';
            width:50%;
            height: 1px;
            background: #cccccc;
            z-index: 0;
        }

        &:last-child {
            width: auto;
            @include emd-phone{ 
                width: calc(50% - 10px);
            }
            .step-title{
                &::after{
                    display: none;
                }
                @include emd-phone{ 
                    &::after{
                        display: block !important;
                    }
                }
            }
        }

        &.is-active{
            .step-number{
                background: #000000;
                color: #fff;
            }
        }
        
        &.is-done{
            .step-number{
                background: #000000;
                color: transparent;
                &::after{
                    top: 0;
                    right: 0px;
                    position: absolute;
                    content: '';
                    width:100%;
                    height: 100%;
                    z-index: 0;
                    background-image: url("data:image/svg+xml,%3Csvg width='12' height='10' viewBox='0 0 12 10' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M11.4685 0.597656H10.5128C10.3788 0.597656 10.2517 0.65918 10.1697 0.764453L4.53274 7.90527L1.82981 4.48047C1.78892 4.42855 1.7368 4.38658 1.67737 4.35769C1.61794 4.3288 1.55273 4.31375 1.48665 4.31367H0.530983C0.439381 4.31367 0.388795 4.41895 0.44485 4.49004L4.18958 9.23418C4.36458 9.45566 4.7009 9.45566 4.87727 9.23418L11.5546 0.772656C11.6107 0.70293 11.5601 0.597656 11.4685 0.597656Z' fill='white'/%3E%3C/svg%3E%0A");
                    background-repeat: no-repeat;
                    background-position: center;
                }
            }
        }

    }
}



.step-companies-list{
    display: flex;
    flex-wrap: wrap;
    width: 100%;
    gap: 10px;
    margin-bottom: 25px;
    label{
        display: flex;
        flex-wrap: wrap;
        flex-direction: column;
        width: 100%;
        border: 1px solid #ccc;
        padding: 15px;
        cursor: pointer;
        p{
            margin: 0;
        }
        input{
            display: none;
        }
        &:has(input:checked){
            border-color:#000000;
            background: #f1f1f1;
        }
    }
}


.customer-signin-link, .customer-signin-password{
    padding: 5px 0;
    color: #1677FF;
    font-size: 14px;
    &:hover, &:focus{
        color:#000000;
    }
}
